/// <reference types="vite/client" />

declare module '*.vue' {
  import type { DefineComponent } from 'vue'
  const component: DefineComponent<object, object, unknown>
  export default component
}

/** Generated by build/multi-site.ts: the sites included in this build. */
declare module 'virtual:sites' {
  import type { SiteConfig } from './platform/site/types'
  export const siteIndex: { id: string; name: string; domains: string[] }[]
  export const defaultSiteId: string | null
  /** True in development, where localhost:3000/<site-id> selects a site. */
  export const allowPathPrefix: boolean
  export function loadSite(id: string): Promise<SiteConfig>
}
